async fn encrypted_local_session_is_reused_and_revocation_creates_a_new_identity(pool: PgPool) {
    let first = local_session(&f).await;
    let cookie = first.cookie.unwrap();
    let original: String = sqlx::query_scalar("SELECT id::text FROM app.browser_logins LIMIT 1")
        .fetch_one(&pool).await.unwrap();
    let repeated = call(&f, "GET", "/api/v2/auth/session", Value::Null, Some(&cookie)).await;
    assert_eq!(repeated.body, first.body, "reading does not extend the fixed session deadline");
    f.store.logout_browser(original.clone().try_into().unwrap()).await.unwrap();
    let renewed = call(&f, "GET", "/api/v2/auth/session", Value::Null, Some(&cookie)).await;
    assert_eq!(renewed.status, StatusCode::OK);
    assert_ne!(renewed.cookie.as_deref(), Some(cookie.as_str()));
    assert!(sqlx::query_scalar::<_,bool>("SELECT revoked_at IS NOT NULL FROM app.browser_logins WHERE id=$1::uuid")
        .bind(&original).fetch_one(&pool).await.unwrap());
    let (total, active): (i64, i64) = sqlx::query_as("SELECT count(*),count(*) FILTER(WHERE revoked_at IS NULL) FROM app.browser_logins")
        .fetch_one(&pool).await.unwrap();
    assert_eq!((total, active), (2, 1));
